<style>
.ce2-burgundy-wax{--bw:#590f2d;--bw-gold:#c8a176;--bw-cream:#faf5ea;background:#210d17;color:#432228;font-family:'Cormorant Garamond',Georgia,serif;font-size:21px}
.ce2-burgundy-wax .bw-overline,.ce2-burgundy-wax .bw-caption,.ce2-burgundy-wax .bw-tiny,.ce2-burgundy-wax .bw-nav,.ce2-burgundy-wax .bw-next,.ce2-burgundy-wax .bw-footer>span{font:600 10px/1.7 'DM Sans',sans-serif;letter-spacing:.24em;text-transform:uppercase}
.ce2-burgundy-wax h2{font-weight:400;font-size:clamp(44px,7vw,76px);line-height:1.07}
.ce2-burgundy-wax h3{font-size:clamp(29px,4vw,45px);font-weight:500}
.ce2-burgundy-wax .bw-nav{position:absolute;z-index:10;top:0;left:0;right:0;display:flex;justify-content:space-between;align-items:center;padding:19px max(24px,calc((100% - 1100px)/2));color:#f8e9cf}
.ce2-burgundy-wax .bw-nav a{text-decoration:none}
.ce2-burgundy-wax .bw-front{min-height:860px;min-height:100svh;display:grid;place-items:center;position:relative;padding:90px 22px;background:radial-gradient(circle at center,#702541 0,#260d19 70%,#130912 100%);overflow:hidden}
.ce2-burgundy-wax .bw-foliage{position:absolute;width:55%;height:80%;background-position:center;background-size:cover;opacity:.5;filter:brightness(.65) saturate(.5);mix-blend-mode:screen;pointer-events:none}
.ce2-burgundy-wax .bw-foliage-left{top:-10%;left:-22%;transform:rotate(-28deg)}
.ce2-burgundy-wax .bw-foliage-right{bottom:-25%;right:-22%;transform:rotate(160deg)}
.ce2-burgundy-wax .bw-presentation{position:relative;width:min(565px,100%);min-height:695px;background:linear-gradient(110deg,#fffaf1,#efe4d7 95%);border:13px solid #f5ede4;outline:1px solid #c99c74;outline-offset:-23px;padding:64px 28px 52px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;box-shadow:0 25px 55px #09020b88;isolation:isolate}
.ce2-burgundy-wax .bw-presentation:before{content:'';position:absolute;inset:28px;border:1px solid #d2bda8;border-radius:190px 190px 8px 8px;pointer-events:none}
.ce2-burgundy-wax .bw-presentation .bw-caption{color:#87684c}.ce2-burgundy-wax .bw-tiny{margin-top:16px;letter-spacing:.12em;color:#7c6c68}
.ce2-burgundy-wax .bw-presentation h1{font:400 clamp(56px,10vw,105px)/.82 'Cormorant Garamond',serif;display:flex;align-items:center;flex-direction:column;letter-spacing:-.045em;margin:44px 0 15px;color:var(--bw)}
.ce2-burgundy-wax .bw-presentation h1 i{font:400 .55em 'Allura',cursive;margin:8px 0 3px;color:#a47e72}
