.ce2-burgundy-wax .bw-emboss{font:400 35px 'Allura',cursive;color:#946477;margin-top:21px}
.ce2-burgundy-wax .bw-next{margin-top:28px;text-decoration:none;border-bottom:1px solid #a7846a;padding-bottom:7px}
.ce2-burgundy-wax .bw-seal-small{position:absolute;bottom:15px;right:calc(50% - min(42vw,315px));display:grid;place-items:center;width:85px;height:85px;border-radius:45%;transform:rotate(12deg);box-shadow:0 9px 18px #0009;background:radial-gradient(circle at 35% 22%,#ac5870,#65122f 75%);border:5px double #c3909b;color:#e3b9a0;font-size:24px}
