.ce2-burgundy-wax .bw-handwriting{font:400 clamp(26px,4vw,39px)/1.33 'Allura',cursive;max-width:700px;margin:30px auto 62px}
.ce2-burgundy-wax .bw-polaroids{display:flex;justify-content:center;align-items:center;max-width:850px;margin:0 auto 85px;gap:0;min-height:360px}
.ce2-burgundy-wax .bw-polaroid{width:47%;aspect-ratio:4/5;background:#fff;padding:12px 12px 55px;box-shadow:0 12px 28px #542a2a2e;overflow:visible}
