.ce2-burgundy-wax .bw-polaroid figcaption{font:400 25px 'Allura',cursive;margin:8px 0 0}
.ce2-burgundy-wax .bw-story-card{max-width:620px;margin:auto;border-top:1px solid #d1bdab;padding:48px 22px}
