.ce2-burgundy-wax .bw-engraving{position:absolute;inset:0;background-position:center;background-size:cover;filter:brightness(.32) sepia(.2);opacity:.56}
.ce2-burgundy-wax .bw-card{position:relative;background:var(--bw-cream);border:12px solid #f2e7d9;outline:1px solid var(--bw-gold);outline-offset:-21px;width:min(590px,100%);padding:60px 35px;text-align:center;box-shadow:0 18px 40px #0006}
