.ce2-burgundy-wax .bw-schedule{padding:100px 24px;background:#efe2d8;text-align:center}
.ce2-burgundy-wax .bw-schedule h2{margin:20px auto}
.ce2-burgundy-wax .bw-schedule-cards{max-width:720px;margin:45px auto;display:grid;grid-template-columns:repeat(3,1fr);gap:11px}
