.ce2-burgundy-wax .bw-schedule-cards strong{font-size:32px;font-weight:400}
.ce2-burgundy-wax .bw-schedule-extra{white-space:pre-line}
.ce2-burgundy-wax .bw-family{background:#fff8ea;text-align:center;padding:90px 24px}
.ce2-burgundy-wax .bw-family h2{margin:13px auto 30px}
.ce2-burgundy-wax .bw-family-list{max-width:600px;margin:auto;display:grid;gap:24px}
.ce2-burgundy-wax .bw-family-list div{border-bottom:1px solid #decaaf;padding:13px 0}
.ce2-burgundy-wax .bw-family-list h3{font-size:29px}.ce2-burgundy-wax .bw-family-list p{white-space:pre-line}
.ce2-burgundy-wax .bw-album{background:#f6f0e9;padding:100px 20px;text-align:center}
.ce2-burgundy-wax .bw-album h2{margin:16px auto 42px}
.ce2-burgundy-wax .bw-album-grid{max-width:1000px;margin:auto;display:grid;grid-template-columns:1.2fr 1fr;grid-template-rows:210px 210px;gap:16px}
.ce2-burgundy-wax .bw-album-image-one{grid-row:span 2}.ce2-burgundy-wax .bw-album-image{height:100%;border:8px solid #fff;box-shadow:0 5px 15px #0002}
.ce2-burgundy-wax .bw-album-quote{font:400 36px 'Allura',cursive;margin:38px auto 0}
.ce2-burgundy-wax .bw-dress{background:#50152e;padding:105px 24px}
.ce2-burgundy-wax .bw-dress-stationery{max-width:650px;background:#fcf5e9;margin:auto;text-align:center;padding:65px 30px;border:1px solid #d4b896}
.ce2-burgundy-wax .bw-dress h2{margin:17px auto}
.ce2-burgundy-wax .bw-swatches{display:flex;gap:9px;justify-content:center;margin:25px auto 36px}
.ce2-burgundy-wax .bw-swatches i{width:45px;height:45px;background:#6b112b}.ce2-burgundy-wax .bw-swatches i:nth-child(2){background:#a96f82}.ce2-burgundy-wax .bw-swatches i:nth-child(3){background:#c19b88}.ce2-burgundy-wax .bw-swatches i:nth-child(4){background:#e9cfb2}
.ce2-burgundy-wax .bw-registry{padding:30px 0 0;margin-top:33px;border-top:1px solid #dccdb9}.ce2-burgundy-wax .bw-registry h3{font:400 35px 'Allura',cursive}
.ce2-burgundy-wax .bw-registry a{display:inline-block;margin-top:16px}
.ce2-burgundy-wax .bw-rsvp{background:#230e1b;position:relative;padding:120px 20px;overflow:hidden}
.ce2-burgundy-wax .bw-rsvp-flower{position:absolute;inset:0;background-size:cover;background-position:center;opacity:.25;filter:brightness(.35) saturate(.5)}
.ce2-burgundy-wax .bw-rsvp-letter{position:relative;background:#fff8ee;max-width:700px;margin:auto;padding:70px clamp(20px,6vw,70px) 30px;text-align:center;box-shadow:0 20px 60px #0009}
.ce2-burgundy-wax .bw-rsvp-letter:before{content:'';position:absolute;inset:14px;border:1px solid #c4a78a;pointer-events:none}
