.ce2-burgundy-wax .bw-note{padding:90px 20px}
.ce2-burgundy-wax .bw-polaroids{min-height:270px;margin-bottom:40px}
.ce2-burgundy-wax .bw-polaroid{padding:7px 7px 37px}
.ce2-burgundy-wax .bw-polaroid figcaption{font-size:17px}
.ce2-burgundy-wax .bw-card{padding:58px 20px}
.ce2-burgundy-wax .bw-schedule-cards{grid-template-columns:1fr}
.ce2-burgundy-wax .bw-album-grid{grid-template-rows:165px 165px;gap:8px}
.ce2-burgundy-wax .bw-album-image{border-width:4px}
}
</style>